@charset "UTF-8";
@font-face {
  font-family: "Fusion Pixel 12 Proportional";
  src: url("data:font/woff2;base64,") format("woff2");
  font-display: swap;
  font-style: normal;
  font-weight: 400;
}
@font-face {
  font-family: "JetBrains Mono";
  src: url("data:font/woff2;base64,") format("woff2");
  font-display: swap;
  font-style: normal;
  font-weight: 400;
}
@font-face {
  font-family: "JetBrains Mono";
  src: url("data:font/woff2;base64,") format("woff2");
  font-display: swap;
  font-style: normal;
  font-weight: 700;
}
body {
  --pixel-font-text: "Source Han Sans CN", "Source Han Sans SC", "Noto Sans CJK SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  --pixel-font-interface: var(--pixel-font-text);
  --pixel-font-identity: "Fusion Pixel 12 Proportional", var(--pixel-font-text);
  --pixel-font-monospace: "JetBrains Mono", "SFMono-Regular", Consolas, "Liberation Mono", var(--pixel-font-text), monospace;
  --pixel-space-1: 4px;
  --pixel-space-2: 8px;
  --pixel-space-3: 12px;
  --pixel-space-4: 16px;
  --pixel-space-6: 24px;
  --pixel-space-8: 32px;
  --pixel-space-12: 48px;
  --pixel-border-decoration: 1px;
  --pixel-border-control: 2px;
  --pixel-border-shell: 3px;
  --pixel-radius: 0;
  --pixel-shadow-control: 2px 2px 0 var(--pixel-shadow-color);
  --pixel-shadow-shell: 4px 4px 0 var(--pixel-shadow-color);
  --pixel-shadow-side-module: 4px 4px 0 var(--pixel-shadow-color);
  --pixel-shadow-cockpit: 5px 5px 0 var(--pixel-shadow-color);
  --pixel-shadow-buffer: 3px 3px 0 var(--pixel-shadow-color);
  --pixel-cockpit-contour: 9px 9px 22px 9px;
  --pixel-cartridge-rail-min: 48px;
  --pixel-cartridge-rail-padding-block: 6px;
  --pixel-cartridge-rail-padding-inline: 8px;
  --pixel-cartridge-rail-gap: 6px;
  --pixel-content-chassis-inset: 8px;
  --pixel-motion-press: 80ms;
  --pixel-motion-state: 120ms;
  --pixel-motion-surface: 160ms;
  --pixel-control-min: 32px;
  --pixel-icon-size: 18px;
  --pixel-state-min-block-size: 48px;
  --pixel-workspace-gap: 12px;
  --pixel-workspace-inset: 12px;
  --pixel-workspace-grid-size: 24px;
}

.theme-light {
  color-scheme: light;
  --accent-h: 188;
  --accent-s: 70%;
  --accent-l: 32%;
  --pixel-accent-hover-shift: -6%;
  --pixel-canvas: #e8eef2;
  --pixel-paper: #f8fbfc;
  --pixel-surface-secondary: #dbe5eb;
  --pixel-text: #182434;
  --pixel-text-muted: #607184;
  --pixel-cyan: #197d8c;
  --pixel-cyan-rgb: 25, 125, 140;
  --pixel-amber: #d48732;
  --pixel-amber-text: #80501e;
  --pixel-amber-rgb: 128, 80, 30;
  --pixel-brick: #ae4e32;
  --pixel-brick-rgb: 174, 78, 50;
  --pixel-line: #d2dde2;
  --pixel-line-strong: #afc0ca;
  --pixel-border-meaningful: #607184;
  --pixel-border-meaningful-rgb: 96, 113, 132;
  --pixel-shadow-color: #8fa5b2;
  --pixel-nav-label: #dcebed;
  --pixel-context-label: #f3eee3;
  --pixel-tree-signal: var(--pixel-cyan);
  --pixel-tree-active-surface: var(--pixel-nav-label);
  --pixel-selection: rgba(25, 125, 140, 0.28);
  --pixel-active-line: #edf5f7;
}

.theme-dark {
  color-scheme: dark;
  --accent-h: 184;
  --accent-s: 55%;
  --accent-l: 58%;
  --pixel-accent-hover-shift: 6%;
  --pixel-canvas: #101821;
  --pixel-paper: #17232d;
  --pixel-surface-secondary: #20313c;
  --pixel-text: #e5edf0;
  --pixel-text-muted: #8fa2ad;
  --pixel-cyan: #58c7cf;
  --pixel-cyan-rgb: 88, 199, 207;
  --pixel-amber: #f0aa4f;
  --pixel-amber-text: #f0aa4f;
  --pixel-amber-rgb: 240, 170, 79;
  --pixel-brick: #ef8b5d;
  --pixel-brick-rgb: 239, 139, 93;
  --pixel-line: #2b3d47;
  --pixel-line-strong: #344854;
  --pixel-border-meaningful: #8fa2ad;
  --pixel-border-meaningful-rgb: 143, 162, 173;
  --pixel-shadow-color: #091016;
  --pixel-nav-label: #203d46;
  --pixel-context-label: #2a2926;
  --pixel-tree-signal: var(--pixel-cyan);
  --pixel-tree-active-surface: var(--pixel-nav-label);
  --pixel-selection: rgba(88, 199, 207, 0.35);
  --pixel-active-line: #1d3039;
}

body {
  --font-interface-theme: var(--pixel-font-interface);
  --font-text-theme: var(--pixel-font-text);
  --font-monospace-theme: var(--pixel-font-monospace);
  --font-text-size: 16px;
  --font-ui-small: 13px;
  --font-ui-medium: 13px;
  --line-height-normal: 1.75;
  --line-height-tight: 1.5;
  --file-line-width: 72ch;
  --p-spacing: 1em;
  --heading-spacing: 2em;
  --inline-title-font: var(--pixel-font-identity);
  --inline-title-line-height: 1.3;
  --inline-title-size: 2em;
  --h1-font: var(--pixel-font-identity);
  --h2-font: var(--pixel-font-identity);
  --h3-font: var(--pixel-font-identity);
  --h4-font: var(--pixel-font-text);
  --h5-font: var(--pixel-font-text);
  --h6-font: var(--pixel-font-text);
  --h1-size: 2em;
  --h2-size: 1.5em;
  --h3-size: 1.25em;
  --h1-line-height: 1.3;
  --h2-line-height: 1.4;
  --h3-line-height: 1.5;
  --h4-line-height: var(--line-height-tight);
  --h5-line-height: var(--line-height-tight);
  --h6-line-height: var(--line-height-tight);
  --code-size: 0.9em;
  --border-width: var(--pixel-border-control);
  --radius-s: var(--pixel-radius);
  --radius-m: var(--pixel-radius);
  --radius-l: var(--pixel-radius);
  --input-radius: var(--pixel-radius);
  --tab-radius-active: var(--pixel-radius);
  --checkbox-radius: var(--pixel-radius);
}

.theme-light,
.theme-dark {
  --background-primary: var(--pixel-paper);
  --background-primary-alt: var(--pixel-surface-secondary);
  --background-secondary: var(--pixel-canvas);
  --background-secondary-alt: var(--pixel-surface-secondary);
  --background-modifier-hover: var(--pixel-surface-secondary);
  --background-modifier-active-hover: var(--pixel-surface-secondary);
  --background-modifier-border: var(--pixel-border-meaningful);
  --background-modifier-border-hover: var(--pixel-cyan);
  --background-modifier-border-focus: var(--pixel-cyan);
  --background-modifier-form-field: var(--pixel-paper);
  --text-normal: var(--pixel-text);
  --text-muted: var(--pixel-text-muted);
  --text-faint: var(--pixel-text-muted);
  --text-accent: hsl(var(--accent-h), var(--accent-s), var(--accent-l));
  --text-accent-hover: hsl(var(--accent-h), var(--accent-s), calc(var(--accent-l) + var(--pixel-accent-hover-shift)));
  --text-warning: var(--pixel-amber-text);
  --text-error: var(--pixel-brick);
  --interactive-normal: var(--pixel-paper);
  --interactive-hover: var(--pixel-surface-secondary);
  --interactive-accent: hsl(var(--accent-h), var(--accent-s), var(--accent-l));
  --interactive-accent-hover: hsl(var(--accent-h), var(--accent-s), calc(var(--accent-l) + var(--pixel-accent-hover-shift)));
  --divider-color: var(--pixel-line);
  --divider-color-hover: var(--pixel-cyan);
  --divider-width: var(--pixel-border-decoration);
  --divider-width-hover: var(--pixel-border-shell);
  --caret-color: var(--pixel-cyan);
  --input-border-width: var(--pixel-border-control);
  --input-border-width-focus: var(--pixel-border-control);
  --input-shadow: var(--pixel-shadow-control);
  --input-shadow-hover: var(--pixel-shadow-control);
  --modal-background: var(--pixel-paper);
  --modal-border-color: var(--pixel-border-meaningful);
  --modal-border-width: var(--pixel-border-control);
  --menu-background: var(--pixel-paper);
  --menu-border-color: var(--pixel-border-meaningful);
  --menu-border-width: var(--pixel-border-control);
  --prompt-background: var(--pixel-paper);
  --prompt-border-color: var(--pixel-border-meaningful);
  --prompt-border-width: var(--pixel-border-control);
  --suggestion-background: var(--pixel-paper);
  --ribbon-background: var(--pixel-canvas);
  --ribbon-background-collapsed: var(--pixel-paper);
  --tab-container-background: var(--pixel-surface-secondary);
  --tab-background-active: var(--pixel-paper);
  --tab-outline-color: var(--pixel-border-meaningful);
  --tab-outline-width: var(--pixel-border-control);
  --status-bar-background: var(--pixel-paper);
  --status-bar-border-color: var(--pixel-border-meaningful);
  --status-bar-border-width: var(--pixel-border-control) 0 0 var(--pixel-border-control);
  --status-bar-radius: var(--pixel-radius);
  --scrollbar-bg: var(--pixel-canvas);
  --scrollbar-thumb-bg: var(--pixel-border-meaningful);
  --scrollbar-active-thumb-bg: var(--pixel-cyan);
  --scrollbar-radius: var(--pixel-radius);
  --titlebar-border-color: var(--pixel-line);
  --titlebar-border-width: var(--pixel-border-decoration);
  --setting-items-background: var(--pixel-paper);
  --setting-items-border-color: var(--pixel-border-meaningful);
  --setting-items-border-width: var(--pixel-border-control);
  --code-background: var(--pixel-surface-secondary);
  --code-normal: var(--pixel-text);
  --callout-border-width: var(--pixel-border-control);
  --callout-border-opacity: 1;
  --callout-radius: var(--pixel-radius);
  --callout-blend-mode: normal;
  --callout-title-color: var(--pixel-text);
  --callout-content-background: transparent;
  --callout-bug: var(--pixel-brick-rgb);
  --callout-default: var(--pixel-cyan-rgb);
  --callout-error: var(--pixel-brick-rgb);
  --callout-example: var(--pixel-cyan-rgb);
  --callout-fail: var(--pixel-brick-rgb);
  --callout-important: var(--pixel-cyan-rgb);
  --callout-info: var(--pixel-cyan-rgb);
  --callout-question: var(--pixel-amber-rgb);
  --callout-success: var(--pixel-cyan-rgb);
  --callout-summary: var(--pixel-cyan-rgb);
  --callout-tip: var(--pixel-cyan-rgb);
  --callout-todo: var(--pixel-cyan-rgb);
  --callout-warning: var(--pixel-amber-rgb);
  --code-white-space: pre;
  --code-border-width: var(--pixel-border-decoration);
  --code-border-color: var(--pixel-line);
  --code-radius: var(--pixel-radius);
  --code-comment: var(--pixel-text);
  --code-function: var(--pixel-amber-text);
  --code-important: var(--pixel-text);
  --code-keyword: var(--pixel-amber-text);
  --code-operator: var(--pixel-text);
  --code-property: var(--pixel-amber-text);
  --code-punctuation: var(--pixel-text);
  --code-string: var(--pixel-text);
  --code-tag: var(--pixel-amber-text);
  --code-value: var(--pixel-text);
  --table-background: var(--pixel-paper);
  --table-border-width: var(--pixel-border-decoration);
  --table-border-color: var(--pixel-border-meaningful);
  --table-white-space: normal;
  --table-header-background: var(--pixel-surface-secondary);
  --table-header-background-hover: var(--pixel-surface-secondary);
